import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.set.difference.v2.js";
import "core-js/modules/es.set.intersection.v2.js";
import "core-js/modules/es.set.is-disjoint-from.v2.js";
import "core-js/modules/es.set.is-subset-of.v2.js";
import "core-js/modules/es.set.is-superset-of.v2.js";
import "core-js/modules/es.set.symmetric-difference.v2.js";
import "core-js/modules/es.set.union.v2.js";
import { ref, computed, onMounted, watch } from 'vue';
import { useStore } from 'vuex';
import { ElMessage, ElMessageBox } from 'element-plus';
import axios from 'axios';
import { API_CONFIG } from '@/config/config';
import defaultAvatar from '@/assets/default-avatar.png';
export default {
  name: 'GroupInfo',
  props: {
    visible: {
      type: Boolean,
      default: false
    },
    groupInfo: {
      type: Object,
      default: () => ({})
    }
  },
  emits: ['update:visible'],
  setup(props, {
    emit
  }) {
    const store = useStore();
    const currentUserId = computed(() => store.state.user.id);
    const currentUser = computed(() => store.state.user);
    const groupMembers = ref([]);
    const isMuted = ref(false);
    const showEditName = ref(false);
    const editGroupName = ref('');
    const showAddMember = ref(false);
    const searchKeyword = ref('');
    const selectedUserIds = ref(new Set());
    const allUsers = ref([]);
    const isGroupOwner = computed(() => {
      return props.groupInfo.creator_id === currentUserId.value;
    });
    const handleMemberClick = async member => {
      // 只有群主且可以移除的成员才触发移除操作
      if (isGroupOwner.value && canRemoveMember(member)) {
        await removeMember(member);
      }
      // 否则不做任何操作（或者可以添加查看成员信息的功能）
    };

    // 检查是否可以移除该成员
    const canRemoveMember = member => {
      // 不能移除自己
      if (member.id === currentUserId.value) {
        return false;
      }

      // 不能移除群主（创建者）
      if (member.id === props.groupInfo.creator_id) {
        return false;
      }
      return true;
    };
    const groupAvatarUrls = computed(() => {
      if (!props.groupInfo) return [defaultAvatar];
      const avatarMembers = props.groupInfo.avatar_members || [];
      console.log("计算 groupAvatarUrls 时的 avatar_members:", avatarMembers);
      // 优先使用 avatar_members
      if (avatarMembers.length > 0) {
        return avatarMembers.slice(0, 9).map(url => getFullUrl(url)).filter(Boolean);
      }

      // 如果没有 avatar_members，使用群成员的头像
      console.log("计算 groupAvatarUrls 时的 groupMembers:", groupMembers.value);
      if (groupMembers.value && groupMembers.value.length > 0) {
        return groupMembers.value.slice(0, 9).map(member => member.photo ? getFullUrl(member.photo) : defaultAvatar);
      }

      // 如果都没有，使用默认头像
      return [defaultAvatar];
    });
    const filteredUsers = computed(() => {
      if (!searchKeyword.value) return allUsers.value;
      return allUsers.value.filter(user => user.username.toLowerCase().includes(searchKeyword.value.toLowerCase()) || user.id.toString().includes(searchKeyword.value));
    });
    const getFullUrl = path => {
      if (!path) return defaultAvatar;
      return path.startsWith('http') ? path : `${API_CONFIG.BASE_URL}${path}`;
    };
    const getAvatarPosition = index => {
      const positions = [{
        top: '0%',
        left: '0%',
        width: '50%',
        height: '50%'
      }, {
        top: '0%',
        left: '50%',
        width: '50%',
        height: '50%'
      }, {
        top: '50%',
        left: '0%',
        width: '50%',
        height: '50%'
      }, {
        top: '50%',
        left: '50%',
        width: '50%',
        height: '50%'
      }, {
        top: '16%',
        left: '16%',
        width: '33%',
        height: '33%'
      }, {
        top: '16%',
        right: '16%',
        width: '33%',
        height: '33%'
      }, {
        bottom: '16%',
        left: '16%',
        width: '33%',
        height: '33%'
      }, {
        bottom: '16%',
        right: '16%',
        width: '33%',
        height: '33%'
      }, {
        top: '33%',
        left: '33%',
        width: '33%',
        height: '33%'
      }];
      return positions[index] || positions[0];
    };
    const getMemberAvatar = member => {
      return member.photo ? getFullUrl(member.photo) : defaultAvatar;
    };

    // const getMemberAvatarById = (memberId) => {
    //   const member = groupMembers.value.find(m => m.id === memberId);
    //   return member?.photo ? getFullUrl(member.photo) : defaultAvatar;
    // };

    const getMemberRole = member => {
      if (member.id === props.groupInfo.creator_id) return '群主';
      return '成员';
    };

    // const getFirstMembers = (members, count) => {
    //   if (!members) return [];
    //   return members.slice(0, count);
    // };

    const close = () => {
      emit('update:visible', false);
    };
    const loadGroupMembers = async () => {
      console.log("获取群信息：", props.groupInfo);
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/members`, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        console.log("群成员数据--2：", response.data);
        if (response.data) {
          groupMembers.value = response.data.group_members || [];
        }
      } catch (error) {
        console.error('加载群成员失败:', error);
        ElMessage.error('加载群成员失败');
      }
    };
    const loadAllUsers = async () => {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/users`, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data) {
          // 过滤掉已经是群成员的用户
          const memberIds = new Set(groupMembers.value.map(m => m.id));
          allUsers.value = response.data.filter(user => !memberIds.has(user.id));
        }
      } catch (error) {
        console.error('加载用户列表失败:', error);
        ElMessage.error('加载用户列表失败');
      }
    };
    const showEditNameDialog = () => {
      editGroupName.value = props.groupInfo.group_name || '';
      showEditName.value = true;
    };
    const cancelEditName = () => {
      showEditName.value = false;
    };
    const confirmEditName = async () => {
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/update-name`, {
          group_id: props.groupInfo.group_id,
          name: editGroupName.value
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          ElMessage.success('群名称修改成功');

          // 1. 关闭编辑对话框
          showEditName.value = false;

          // 2. 更新Vuex store中的群组信息
          store.commit('chat/UPDATE_JOINED_GROUP', {
            group_id: props.groupInfo.group_id,
            name: editGroupName.value,
            // 保持其他字段不变
            ...props.groupInfo
          });

          // 3. 通知父组件更新群信息
          emit('group-updated');

          // 4. 关闭整个群信息对话框
          emit('update:visible', false);

          // 4. 可选：延迟关闭整个群信息对话框
          setTimeout(() => {
            emit('update:visible', false); // 关闭群信息对话框
          }, 1); // 1秒后关闭
        } else {
          ElMessage.error(response.data.message || '修改失败');
          showEditName.value = false; // 失败时也关闭编辑对话框
        }
      } catch (error) {
        console.error('修改群名称失败:', error);
        ElMessage.error('修改群名称失败');
        showEditName.value = false; // 出错时关闭编辑对话框
      }
    };
    const toggleMute = async () => {
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/mute?user_id=${currentUserId.value}`, {
          muted: !isMuted.value,
          user_id: currentUserId.value
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          isMuted.value = !isMuted.value;
          ElMessage.success(isMuted.value ? '已开启消息免打扰' : '已关闭消息免打扰');
        }
      } catch (error) {
        console.error('设置消息免打扰失败:', error);
        ElMessage.error('设置失败');
      }
    };
    const removeMember = async member => {
      try {
        await ElMessageBox.confirm(`确定要将 ${member.username} 移出群聊吗？`, '确认移除', {
          type: 'warning'
        });
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/remove-member`, {
          group_id: props.groupInfo.id,
          user_id: member.id
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          ElMessage.success('成员已移除');
          // 重新加载群成员
          await loadGroupMembers();
          await loadAllUsers();
          emit('group-updated');
        }
      } catch (error) {
        if (error !== 'cancel') {
          console.error('移除成员失败:', error);
          ElMessage.error('移除成员失败');
        }
      }
    };
    const exitGroup = async () => {
      try {
        await ElMessageBox.confirm('确定要退出该群聊吗？退出后将不再接收该群消息', '确认退出', {
          type: 'warning'
        });
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/exit`, {
          group_id: props.groupInfo.id
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          ElMessage.success('已退出群聊');
          close();
          // 通知父组件处理退出后的逻辑
          emit('group-exited');
        }
      } catch (error) {
        if (error !== 'cancel') {
          console.error('退出群聊失败:', error);
          ElMessage.error('退出群聊失败');
        }
      }
    };
    const showAddMemberDialog = async () => {
      await loadAllUsers();
      showAddMember.value = true;
      selectedUserIds.value.clear();
      searchKeyword.value = '';
    };
    const closeAddMemberDialog = () => {
      showAddMember.value = false;
    };
    const selectUser = user => {
      if (selectedUserIds.value.has(user.id)) {
        selectedUserIds.value.delete(user.id);
      } else {
        selectedUserIds.value.add(user.id);
      }
    };
    const isUserSelected = userId => {
      return selectedUserIds.value.has(userId);
    };
    const confirmAddMembers = async () => {
      if (selectedUserIds.value.size === 0) {
        ElMessage.warning('请选择要添加的成员');
        return;
      }
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/add-members`, {
          group_id: props.groupInfo.id,
          user_ids: Array.from(selectedUserIds.value)
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          ElMessage.success('成员添加成功');
          // 重新加载群成员
          await loadGroupMembers();
          await loadAllUsers();
          closeAddMemberDialog();
          emit('group-updated');
        }
      } catch (error) {
        console.error('添加成员失败:', error);
        ElMessage.error('添加成员失败');
      }
    };
    // 在 setup 函数中添加
    watch(() => props.visible, async newVisible => {
      if (newVisible && props.groupInfo.group_id) {
        console.log("GroupInfo 对话框显示，开始加载数据");
        await loadGroupMembers();

        // 加载群免打扰状态
        try {
          const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/mute-status?user_id=${currentUserId.value}`, {
            headers: {
              Authorization: `Bearer ${store.state.token}`
            }
          });
          if (response.data.success) {
            isMuted.value = response.data.muted;
          }
        } catch (error) {
          console.error('获取免打扰状态失败:', error);
        }
      }
    });
    onMounted(async () => {
      console.log("GroupInfo 接收到的 groupInfo:", props.groupInfo);
      console.log("GroupInfo visible 状态:", props.visible);
      console.log("group_id :", props.groupInfo.group_id);
      if (props.visible && props.groupInfo.group_id) {
        console.log("GroupInfo 接收到的 groupInfo:", props.groupInfo);
        await loadGroupMembers();

        // 加载群免打扰状态
        try {
          const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/mute-status?user_id=${currentUserId.value}`, {
            headers: {
              Authorization: `Bearer ${store.state.token}`
            }
          });
          if (response.data.success) {
            isMuted.value = response.data.muted;
          }
        } catch (error) {
          console.error('获取免打扰状态失败:', error);
        }
      }
    });
    return {
      currentUserId,
      groupMembers,
      currentUser,
      isMuted,
      showEditName,
      editGroupName,
      showAddMember,
      searchKeyword,
      filteredUsers,
      isGroupOwner,
      groupAvatarUrls,
      getFullUrl,
      getAvatarPosition,
      getMemberAvatar,
      getMemberRole,
      close,
      showEditNameDialog,
      cancelEditName,
      confirmEditName,
      toggleMute,
      removeMember,
      exitGroup,
      handleMemberClick,
      canRemoveMember,
      showAddMemberDialog,
      closeAddMemberDialog,
      selectUser,
      isUserSelected,
      confirmAddMembers
    };
  }
};
